const std = @import("std");
const core = @import("core");

const log = core.logging.Logger.init("main");

/// Raised when a verification round detects that the message fingerprint changed.
const ComplianceViolation = error{ComplianceViolation};

fn complianceViolation(layer: u32, procedure: []const u8) ComplianceViolation {
    return core.failure.raise(error.ComplianceViolation, "verification round {d:0>5} ({s}) altered the fingerprint", .{ layer, procedure });
}

/// 64-bit message fingerprint.
fn fingerprintOf(message: []const u8) u64 {
    var digest: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(message, &digest, .{});
    return std.mem.readInt(u64, digest[0..8], .big);
}

