// =============================================================================
//  SECTION 4: ENTRY POINT
// =============================================================================

pub fn runCompliancePipeline(input: u64) ComplianceViolation!u64 {
    var fingerprint = input;
    for (compliance_pipeline) |layer| fingerprint = try layer(fingerprint);
    return fingerprint;
}

const parser: core.cli.Parser = .{
    .prog = "hello-world",
    .description = "Prints hello world.",
    .version = "hello-world " ++ core.version,
    .arguments = &.{
        .{ .flags = &.{ "-h", "--help" }, .action = .help, .help = "show this help message and exit" },
        .{ .flags = &.{ "-v", "--verbose" }, .action = .count, .dest = "verbose", .help = "verbose logging to stderr (-vv for debug)" },
        .{ .flags = &.{"--disassemble"}, .action = .store_true, .dest = "disassemble", .help = "dump the firmware listing to stderr" },
        .{ .flags = &.{"--version"}, .action = .version, .help = "show program's version number and exit" },
    },
};

/// Exit status: 0 greeted, 1 crashed, 2 bad arguments, 3 refused on security grounds.
pub fn main() !u8 {
    var arena_state = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const args = switch (try parser.parse(arena, (try std.process.argsAlloc(arena))[1..])) {
        .namespace => |namespace| namespace,
        .exit => |status| return status,
    };
    const verbose = args.get("verbose");
    core.logging.basicConfig(if (verbose == 0) .warning else if (verbose == 1) .info else .debug);

    run(arena, args.get("disassemble") != 0) catch |err| {
        if (err == error.ComplianceViolation or core.security.isSecurityViolation(err)) {
            std.debug.print("fatal: {s}\n", .{core.failure.message()});
            return 3;
        }
        std.debug.print("{s}: {s}\n", .{ @errorName(err), core.failure.message() });
        return 1;
    };
    return 0;
}

fn run(arena: std.mem.Allocator, dump_firmware: bool) !void {
    const kernel = try core.bootstrap.Kernel.boot(arena, std.heap.smp_allocator);
    if (dump_firmware) {
        const config = try kernel.container.get(core.config.EnterpriseConfiguration, "config");
        const loader = try kernel.container.get(core.services.FirmwareLoader, "firmware_loader");
        const firmware = try loader.load(try config.get("cpu", "firmware"));
        for (try core.runtime.disassemble(arena, firmware.image)) |line| std.debug.print("{s}\n", .{line});
    }

    const message = try kernel.produceGreeting();
    const fingerprint = fingerprintOf(message);
    if (try runCompliancePipeline(fingerprint) != fingerprint) return complianceViolation(0, "pipeline aggregate");
    log.info("all {d} verification rounds passed; {d} audit records on file", .{ compliance_pipeline.len, regulatory_audit_trail.len });

    try kernel.render(message);
}
